#ifndef SLOTMAP_H
#define SLOTMAP_H

#include <stdint.h>

#define SM_MAX_CAP 64
#define SM_KEY_MAX 15

enum { SM_INSERTED = 0, SM_UPDATED = 1, SM_FULL = -1, SM_BADKEY = -2 };

