    char key[SM_KEY_MAX + 1];
    int32_t value;
    int state; /* 0 empty, 1 used, 2 gone */
} sm_slot;

typedef struct {
    sm_slot slots[SM_MAX_CAP];
    int cap;
    int used;
    int gone;
} slotmap;

